import {extraExercises} from './sql-extra.mjs?v=20';
import {datasets,dialects,sqlExamples,setupScript} from './sql-data.mjs?v=20';
import {workStore} from './work-store.mjs?v=15';
import {escapeHTML as e} from './engine.mjs?v=17';
export const exercises=[
 {id:'city',dataset:'college',title:'1. Filter students',prompt:'Display StudentName and Age for students from Polokwane, sorted by StudentName.',hint:'Filter City with a single-quoted string, then sort the selected rows.',answer:"SELECT StudentName, Age FROM Students\nWHERE City = 'Polokwane' ORDER BY StudentName;",expected:'Five rows: David (21), Grace (25), John (26), Lebo (18) and Maria (22).'},
 {id:'marks',dataset:'college',title:'2. Count missing marks',prompt:'Count enrolments with no mark yet. Use alias Unmarked.',hint:'Use IS NULL, not = NULL.',answer:'SELECT COUNT(*) AS Unmarked FROM Enrolments WHERE Mark IS NULL;',expected:'Unmarked = 3.'},
 {id:'fees',dataset:'college',title:'3. Summarise fees',prompt:'Return the number of courses, total fees and average fee.',hint:'Use COUNT(*), SUM(Fee) and AVG(Fee).',answer:'SELECT COUNT(*) AS CourseCount, SUM(Fee) AS TotalFees, AVG(Fee) AS AverageFee FROM Courses;',expected:'CourseCount = 4, TotalFees = 5650, AverageFee = 1412.5.'},
 {id:'join',dataset:'college',title:'4. Join students to marks',prompt:'Display StudentName, CourseID and Mark for all enrolments. Sort by StudentID then CourseID.',hint:'Join Students to Enrolments on StudentID. Qualify ambiguous column names with aliases.',answer:'SELECT s.StudentName, e.CourseID, e.Mark\nFROM Students AS s JOIN Enrolments AS e ON e.StudentID = s.StudentID\nORDER BY s.StudentID, e.CourseID;',expected:'40 rows. Lebo has course 1 mark 40 and course 2 mark NULL at the beginning.'},
 {id:'groups',dataset:'college',title:'5. Group by city',prompt:'Return each City and the number of Students in it, sorted by City.',hint:'Select City and COUNT(*); GROUP BY City.',answer:'SELECT City, COUNT(*) AS StudentCount FROM Students GROUP BY City ORDER BY City;',expected:'Four cities, each with StudentCount = 5.'},
 {id:'create',dataset:'college',title:'6. Add a constrained table',prompt:'Create PracticeNotes with integer NoteID primary key and non-NULL NoteText VARCHAR(120). Insert note 1 with text SQL practice, then query it.',hint:'Use CREATE TABLE, INSERT with named columns, and SELECT. Reset before creating the same table again.',answer:"CREATE TABLE PracticeNotes (NoteID INTEGER PRIMARY KEY, NoteText VARCHAR(120) NOT NULL);\nINSERT INTO PracticeNotes (NoteID, NoteText) VALUES (1, 'SQL practice');\nSELECT * FROM PracticeNotes;",expected:'One row: NoteID = 1, NoteText = SQL practice. It is a custom table in this open workspace.'},
 {id:'stock',dataset:'shop',title:'7. Filter book prices',prompt:'Show Title and Price for books priced at least 200, ordered by Price descending then BookID.',hint:'Filter Price with >= 200. List both sort expressions.',answer:'SELECT Title, Price FROM Books WHERE Price >= 200 ORDER BY Price DESC, BookID;',expected:'Four rows: City Lights (240), Local Histories (240), The Journey (205), Numbers Around Us (205).'},
 {id:'sales',dataset:'shop',title:'8. Count sales per book',prompt:'Display every book title and the number of sale records, including books with no sales. Use LEFT JOIN and count SaleID.',hint:'COUNT(s.SaleID) counts matches. COUNT(*) would count a preserved unmatched book row too.',answer:'SELECT b.Title, COUNT(s.SaleID) AS SaleCount\nFROM Books AS b LEFT JOIN Sales AS s ON s.BookID = b.BookID\nGROUP BY b.BookID, b.Title ORDER BY b.BookID;',expected:'12 rows. The first four books have 2 sale records each and the other eight have 1 each in the original dataset.'}
];
const cleanDraft=raw=>({code:typeof raw?.code==='string'?raw.code.slice(0,30000):''});
exercises.push(...extraExercises);
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function sqlPage({view,id,sidebar}){
 const pref=workStore.read('sql-settings',{dataset:'college',mode:'sqlserver'},raw=>({dataset:datasets[raw?.dataset]?raw.dataset:'college',mode:dialects[raw?.mode]?raw.mode:'sqlserver'}));let dataset=pref.dataset,mode=pref.mode;const restored=/^draft-(college|shop)-(sqlserver|postgresql|mysql)$/.exec(id||'');if(restored){dataset=restored[1];mode=restored[2];}const requested=sqlExamples.find(x=>x.id===id);if(requested)dataset=requested.dataset;
 let worker=null,serial=0,pending=null,timer=null,disposed=false,busy=false,selectedTask='',restartNotice='';
 const key=()=>`sql:${dataset}:${mode}`;const sample=(ex)=>typeof ex.code==='function'?ex.code(mode):ex.code;
 let draft=workStore.read(key(),{code:sample(sqlExamples.find(x=>x.dataset===dataset))},cleanDraft);if(requested)draft.code=sample(requested);
 view.innerHTML=`<p class="breadcrumb"><a href="#db">Databases</a><span>/</span><strong>SQL workspace</strong></p><p class="eyebrow">WRITE . RUN . EXPLORE</p><h1>Your SQL practice space.</h1><p class="lede">Choose your dialect and a fictional dataset. Write a query, run it and inspect the results.</p><div class="sql-engine-note"><strong>Browser practice engine: SQLite.</strong> SQL Server, PostgreSQL and MySQL are compatibility modes for the documented teaching subset, not live server connections. <button type="button" class="text-link" id="sql-show-limits">See supported syntax and differences</button>.</div><div class="sql-toolbar"><label class="field-label">SQL dialect<select id="sql-mode">${Object.entries(dialects).map(([k,v])=>`<option value="${k}" ${k===mode?'selected':''}>${v}</option>`).join('')}</select></label><label class="field-label">Demo dataset<select id="sql-dataset">${Object.entries(datasets).map(([k,v])=>`<option value="${k}" ${k===dataset?'selected':''}>${e(v.title)}</option>`).join('')}</select></label><button class="button secondary" id="sql-reset">Reset demo data</button></div><p class="muted sql-session-note">Draft SQL saves per dataset and dialect in this browser. Table changes last only while this workspace stays open. A reload, module change, reset, stop or timeout restores the demo.</p><div class="sql-layout"><section class="panel sql-main"><div class="sql-example-picker"><label class="field-label">Worked example<select id="sql-example"></select></label><button class="button secondary" id="sql-load">Load example</button></div><p id="sql-example-help" class="muted"></p><label class="field-label" for="sql-editor">SQL editor</label><textarea id="sql-editor" class="editor" rows="13" maxlength="30000" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off">${e(draft.code)}</textarea><div class="button-row"><button class="button" id="sql-run" disabled>Run SQL</button><button class="button secondary" id="sql-stop" disabled>Stop query</button><button class="button secondary" id="sql-download-query">Download query .sql</button></div><p class="muted sql-shortcut">Ctrl+Enter or ⌘+Enter runs your query. Up to 20 statements per run; results show up to 500 rows per statement.</p><p id="sql-status" role="status">Loading the local SQL engine...</p><div id="sql-results" aria-live="polite"></div></section><aside class="panel sql-schema" style="position:static;height:auto;overflow:visible"><h2>Explore the data</h2><p id="sql-data-description"></p><div id="sql-schema"></div><button class="button secondary" id="sql-download-data">Download demo setup .sql</button><p class="muted">Use the setup script in an empty database in your chosen native DBMS. The scripts use explicitly supplied IDs.</p></aside></div><section class="panel sql-challenges"><h2>Try a challenge</h2><label class="field-label">Choose a task<select id="sql-task"><option value="">Choose a challenge...</option>${exercises.map(x=>`<option value="${x.id}">${e(x.title)} (${datasets[x.dataset].title})</option>`).join('')}</select></label><div id="sql-task-panel"><p class="muted">Select a challenge, write SQL in the editor, then run an attempt before revealing the worked answer.</p></div></section><details class="panel sql-limits" id="sql-limits"><summary>Supported syntax and dialect differences</summary><p>All queries run locally using sql.js (SQLite compiled to WebAssembly). This is an introductory SQL practice sandbox. It is not Microsoft SQL Server, PostgreSQL or MySQL.</p><ul><li>Practise SELECT, WHERE, ORDER BY, DISTINCT, joins, subqueries, common-table expressions, GROUP BY, HAVING, COUNT, SUM, AVG, MIN, MAX, ROUND, COALESCE, INSERT, UPDATE, DELETE, basic CREATE/ALTER/DROP TABLE, views and indexes supported by SQLite.</li><li>SQL Server mode adapts a whole-number TOP on one simple SELECT to a row limit, and removes an unquoted dbo. prefix. SQL Server/MySQL DROP INDEX ... ON table is adapted. PostgreSQL/MySQL use LIMIT. Literal strings and quoted names are not rewritten.</li><li>Generated IDs (IDENTITY, SERIAL, AUTO_INCREMENT), server administration, stored procedures, triggers, native date/string functions and transaction commands are not implemented. Use explicit primary-key values and native tools for those features.</li><li>SQLite does not reproduce native DBMS type, precision, string-length, collation, date, permission or optimiser behaviour. A query that runs here is not proof of identical behaviour on a native server. Use portable GROUP BY lists; the sandbox does not enforce every native grouping rule.</li><li>Each run is atomic: a failed batch is rolled back. Foreign keys are enabled. Results are capped at 500 rows per statement, queries time out after 4 seconds, and database pages are limited to about 32 MB. Stop/timeout reloads the demo. Avoid huge cross joins and recursive queries.</li><li>Each tab has its own in-memory database. Saved drafts still share the browser profile, so this is practice, not a private student account or secure assessment.</li></ul><div class="scroll-table"><table class="db-table"><caption>Native dialect reference (not all syntax runs in this browser)</caption><thead><tr><th>Feature</th><th>SQL Server</th><th>PostgreSQL</th><th>MySQL</th></tr></thead><tbody><tr><th>First five rows</th><td>SELECT TOP (5) ... ORDER BY ...</td><td>... ORDER BY ... LIMIT 5</td><td>... ORDER BY ... LIMIT 5</td></tr><tr><th>Generated key</th><td>INT IDENTITY(1,1)</td><td>INTEGER GENERATED BY DEFAULT AS IDENTITY</td><td>INT AUTO_INCREMENT</td></tr><tr><th>Identifier quoting</th><td>[StudentName]</td><td>"StudentName"</td><td>\u0060StudentName\u0060</td></tr><tr><th>String concatenation</th><td>CONCAT(a, b)</td><td>a || b</td><td>CONCAT(a, b)</td></tr><tr><th>Drop index</th><td>DROP INDEX idx ON table_name</td><td>DROP INDEX idx</td><td>DROP INDEX idx ON table_name</td></tr></tbody></table></div><a class="text-link" href="#db-resources">Official documentation and more resources</a></details><dialog id="sql-reset-dialog" aria-labelledby="sql-reset-title"><h2 id="sql-reset-title">Reload the demo dataset?</h2><p id="sql-reset-message">This removes changes made to the open practice database, including custom tables. Your SQL draft is kept.</p><div class="button-row"><button class="button secondary" id="sql-reset-cancel">Keep working</button><button class="button" id="sql-reset-confirm">Load fresh demo</button></div></dialog>`;
 const $=s=>view.querySelector(s),editor=$('#sql-editor');
 const save=()=>workStore.write(key(),{code:editor.value});const saveSettings=()=>workStore.write('sql-settings',{dataset,mode});
 function controls(running){busy=running;$('#sql-run').disabled=running||!worker;$('#sql-stop').disabled=!running;$('#sql-reset').disabled=running;$('#sql-mode').disabled=running;$('#sql-dataset').disabled=running;$('#sql-load').disabled=running;$('#sql-task').disabled=running;}
 function taskState(){return selectedTask?workStore.read(`sqltask:${selectedTask}:${mode}`,{attempted:false,hint:false,revealed:false},r=>({attempted:!!r?.attempted,hint:!!r?.hint,revealed:!!r?.revealed})):null;}
 function renderTask(){const task=exercises.find(t=>t.id===selectedTask);if(!task)return;const state=taskState();$('#sql-task-panel').innerHTML=`<h3>${e(task.title)}</h3><p>${e(task.prompt)}</p><p class="muted">Use the original ${e(datasets[task.dataset].title)} demo. If you changed its data, reset it before comparing expected results. This is a self-check challenge; running a query does not mark it correct.</p><div class="button-row"><button class="button secondary" id="sql-task-hint">Hint</button><button class="button secondary" id="sql-task-answer" ${state.attempted?'':'disabled'}>Reveal worked answer</button></div><p class="note" id="sql-task-hint-text" ${state.hint?'':'hidden'}>${e(task.hint)}</p><section class="model-answer" id="sql-task-answer-text" ${state.attempted&&state.revealed?'':'hidden'}><h3>Worked answer</h3><pre><code>${e(task.answer)}</code></pre><p>${e(task.expected)}</p><p>Compare the columns, row values and ordering from your query with this answer.</p></section>`;
 $('#sql-task-hint').onclick=()=>{state.hint=true;workStore.write(`sqltask:${selectedTask}:${mode}`,state);$('#sql-task-hint-text').hidden=false;};$('#sql-task-answer').onclick=()=>{if(!state.attempted)return;state.revealed=true;workStore.write(`sqltask:${selectedTask}:${mode}`,state);$('#sql-task-answer-text').hidden=false;};}
 function examples(){const list=sqlExamples.filter(x=>x.dataset===dataset);$('#sql-example').innerHTML=list.map(x=>`<option value="${x.id}" ${requested?.id===x.id?'selected':''}>${e(x.title)}</option>`).join('');$('#sql-example-help').textContent='Choose an example and select Load example to replace the editor text.';$('#sql-data-description').textContent=datasets[dataset].description;}
 function showSchema(rows){$('#sql-schema').innerHTML=rows.map(([name,type,definition])=>`<details><summary>${e(name)} <small>${e(type)}</small></summary><pre><code>${e(definition||'')}</code></pre>${type==='table'||type==='view'?`<button class="button secondary" data-preview="${e(name)}">Preview rows</button>`:''}</details>`).join('');view.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{editor.value=mode==='sqlserver'?`SELECT TOP (20) * FROM [${b.dataset.preview.replaceAll(']',']]')}];`:`SELECT * FROM "${b.dataset.preview.replaceAll('"','""')}" LIMIT 20;`;save();run();});}
 function renderResults(results){$('#sql-results').innerHTML=results.map(r=>`<section class="sql-result"><h3>Statement ${r.statement}${r.adapted?' . dialect syntax adapted':''}</h3>${r.columns.length?`<p>${r.values.length}${r.truncated?'+':''} row${r.values.length===1?'':'s'} displayed${r.truncated?' . display capped at 500':''}.</p><div class="scroll-table"><table class="db-table"><thead><tr>${r.columns.map(c=>`<th scope="col">${e(c)}</th>`).join('')}</tr></thead><tbody>${r.values.map(row=>`<tr>${row.map(v=>`<td>${v===null?'<span class="sql-null">NULL</span>':e(String(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${r.values.length?'':'<p>No matching rows.</p>'}`:`<p>Statement completed. ${r.changed===null?'Structure updated.':r.changed+' row(s) affected.'}</p>`}</section>`).join('');}
 function start(notice=''){restartNotice=notice;worker?.terminate();clearTimeout(timer);worker=new Worker(new URL('./sql-worker.js?v=20',import.meta.url));const current=worker;worker.onmessage=event=>{if(disposed||current!==worker||event.data.id!==pending?.id)return;clearTimeout(timer);const request=pending;pending=null;controls(false);const msg=event.data;if(!msg.ok){$('#sql-status').textContent=msg.error+' No changes from this failed run were kept.';$('#sql-status').className='runner-error';return;}showSchema(msg.schema);if(request.action==='run'){renderResults(msg.results);$('#sql-status').textContent=`Finished in ${Math.round(performance.now()-request.started)} ms. ${msg.results.length} statement(s) executed.`;}else{$('#sql-status').textContent=`${restartNotice}${restartNotice?' ':''}${datasets[dataset].title} demo ready. Write a query or load an example.`;restartNotice='';$('#sql-results').innerHTML='';}$('#sql-status').className='sql-ready';};worker.onerror=()=>{clearTimeout(timer);worker?.terminate();worker=null;pending=null;controls(false);$('#sql-status').textContent='The SQL engine could not load. Check your connection and choose Reset demo data to retry. Your draft is still available.';$('#sql-status').className='runner-error';};send('init',15000);}
 function send(action,timeout){if(action==='run')$('#sql-results').innerHTML='';const id=++serial;pending={id,action,started:performance.now()};controls(true);$('#sql-status').className='';$('#sql-status').textContent=action==='init'?'Loading the local SQL engine...':'Running SQL...';worker.postMessage({id,action,dataset,mode,code:editor.value});timer=setTimeout(()=>{if(disposed||pending?.id!==id)return;const wasRun=action==='run';worker.terminate();worker=null;pending=null;controls(false);$('#sql-results').innerHTML='';if(wasRun){start('Query exceeded 4 seconds and was stopped. Original demo restored; your SQL draft is kept.');}else{$('#sql-status').textContent='The SQL engine took too long to load. Check your connection and use Reset demo data to retry.';$('#sql-status').className='runner-error';}},timeout);}
 function run(){if(busy||!worker)return;if(!editor.value.trim()){$('#sql-status').textContent='Write an SQL statement first.';return;}save();if(selectedTask){const st=taskState();st.attempted=true;workStore.write(`sqltask:${selectedTask}:${mode}`,st);renderTask();}send('run',4000);}
 function reset(nextDataset=dataset,after=()=>{}){const dialog=$('#sql-reset-dialog');$('#sql-reset-confirm').onclick=()=>{save();const changing=dataset!==nextDataset;dataset=nextDataset;if(changing){selectedTask='';$('#sql-task').value='';$('#sql-task-panel').innerHTML='<p class="muted">Choose a challenge above.</p>';}$('#sql-dataset').value=dataset;draft=workStore.read(key(),{code:sample(sqlExamples.find(x=>x.dataset===dataset))},cleanDraft);editor.value=draft.code;examples();saveSettings();dialog.close();after();start();};$('#sql-reset-cancel').onclick=()=>{$('#sql-dataset').value=dataset;$('#sql-task').value=selectedTask;dialog.close();};dialog.oncancel=()=>{$('#sql-dataset').value=dataset;$('#sql-task').value=selectedTask;};dialog.showModal();}
 editor.oninput=save;editor.onkeydown=event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();run();}};$('#sql-run').onclick=run;$('#sql-stop').onclick=()=>{if(!busy)return;start('Query stopped. Original demo restored; your SQL draft is kept.');$('#sql-results').innerHTML='';};$('#sql-reset').onclick=()=>reset();$('#sql-dataset').onchange=event=>reset(event.target.value);$('#sql-mode').onchange=event=>{save();mode=event.target.value;const fallback=sample(sqlExamples.find(x=>x.id===$('#sql-example').value)||sqlExamples[0]);editor.value=workStore.read(key(),{code:fallback},cleanDraft).code;saveSettings();$('#sql-results').innerHTML='';if(selectedTask)renderTask();$('#sql-status').textContent='Dialect changed. Existing table data is unchanged; review the syntax before running.';};$('#sql-example').onchange=()=>{$('#sql-example-help').textContent=sqlExamples.find(x=>x.id===$('#sql-example').value)?.explain||'';};$('#sql-load').onclick=()=>{const ex=sqlExamples.find(x=>x.id===$('#sql-example').value);editor.value=sample(ex);$('#sql-example-help').textContent=ex.explain;save();};$('#sql-task').onchange=event=>{const task=exercises.find(t=>t.id===event.target.value);if(!task){selectedTask='';$('#sql-task-panel').innerHTML='<p class="muted">Choose a challenge above.</p>';return;}const choose=()=>{selectedTask=task.id;$('#sql-task').value=selectedTask;renderTask();};if(task.dataset!==dataset)reset(task.dataset,choose);else choose();};$('#sql-download-query').onclick=()=>download(`studylab-${mode}-query.sql`,editor.value);$('#sql-download-data').onclick=()=>download(`studylab-${dataset}-${mode}-setup.sql`,setupScript(dataset,mode));
 $('#sql-show-limits').onclick=()=>{const limits=$('#sql-limits');limits.open=true;limits.scrollIntoView({behavior:'smooth',block:'start'});limits.querySelector('summary').focus();};examples();saveSettings();sidebar();start();return ()=>{disposed=true;save();clearTimeout(timer);worker?.terminate();};
}
